input.content:
#Requires -Version 7.4
# Tests the #2722 licence skip message on a real tenant, using the fix branch with #2708 merged.
# Usage: pwsh -NoProfile -File Test-LicenceMessage.ps1 -TenantId jozra.com
param([Parameter(Mandatory)] [string] $TenantId)

$repo = Join-Path $PSScriptRoot 'tenant-test'
Get-Module Maester | Remove-Module -Force
Import-Module (Join-Path $repo 'powershell/Maester.psd1') -Force

Connect-Maester -TenantId $TenantId -Service Graph

$ctx = Get-MgContext
Write-Host "`nSigned in to $($ctx.TenantId) as $($ctx.Account)" -ForegroundColor Cyan

# What the licence gate looks for: the Entra ID P2 plan, the Agent 365 plan, and the Agent 365 / E7 SKUs.
$skus = Invoke-MgGraphRequest -Uri 'v1.0/subscribedSkus' -OutputType PSObject
$watch = @{
    'eec0eb4f-6444-4f95-aba0-50c24d67f998' = 'AAD_PREMIUM_P2 plan'
    'd0ce5ebb-9db0-491f-b780-8973a1d815fe' = 'AGENT_365 plan'
    '796a6fb4-740b-4d36-bf56-9c12ca7fa069' = 'Agent 365 SKU'
    '9a18296a-025f-4e37-9ffa-30bf8d1ce775' = 'Microsoft 365 E7 SKU'
}
Write-Host "`nLicences the gate looks for:" -ForegroundColor Cyan
foreach ($sku in $skus.value) {
    if ($sku.capabilityStatus -ne 'Enabled') { continue }
    if ($watch.ContainsKey($sku.skuId)) { Write-Host "  $($sku.skuPartNumber): $($watch[$sku.skuId])" }
    foreach ($plan in $sku.servicePlans) {
        if ($watch.ContainsKey($plan.servicePlanId)) { Write-Host "  $($sku.skuPartNumber) -> $($plan.servicePlanName) ($($plan.provisioningStatus)): $($watch[$plan.servicePlanId])" }
    }
}

$row = Invoke-MtTest -Id 'MT.1181'
Write-Host "`nMT.1181" -ForegroundColor Cyan
[pscustomobject]@{
    Result       = $row.Result
    ReasonCode   = $row.ReasonCode
    ReasonDetail = $row.ReasonDetail
    TestSkipped  = $row.ResultDetail.TestSkipped
    TestResult   = $row.ResultDetail.TestResult
} | Format-List

Disconnect-Maester

